
const express = require("express");

const app = express();
const PORT = 3000;

app.use(express.json());

// Base de données temporaire (vide au début)
let appointments = [];
let nextId = 1;

// Route 1 : Page d'accueil
app.get("/", (req, res) => {
  res.send("SmartCare Appointment Service fonctionne !");
});

// Route 2 : Liste des rendez-vous
app.get("/api/appointments", (req, res) => {
  res.json({
    message: "Liste des rendez-vous",
    count: appointments.length,
    appointments: appointments
  });
});

// Lancer le serveur
app.listen(PORT, () => {
  console.log(`Serveur SmartCare lancé sur http://localhost:${PORT}`);
});